target.css:
:root {
  --ink: #27372c;
  --paper: #fffdf7;
  --line: #d9dfcf;
  --leaf: #426b45;
  --apple-red: #d95645;
  --cream: #f1f4e9;
}

.tasting-card {
  width: 450px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
footer,
.details {
  display: flex;
  align-items: center;
}

.card-header,
footer {
  justify-content: space-between;
}

.card-header {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--leaf);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h2 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.ticket {
  padding: 5px 8px;
  border-radius: 7px;
  background: var(--apple-red);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.details {
  gap: 10px;
  padding: 12px 0;
}

.apple {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  background: var(--cream);
  font-size: 21px;
}

.details p {
  margin: 0;
  font-size: 14px;
  line-height: 1.45;
}

footer {
  color: var(--leaf);
  font-size: 12px;
  font-weight: 600;
}

button {
  border: 0;
  border-radius: 7px;
  padding: 7px 11px;
  background: var(--leaf);
  color: var(--paper);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
}
